mapper.select:
SELECT ss.*
FROM slot_sessions ss
WHERE ss.assignment_id = #{assignmentId}
  AND ss.start_at >= #{startAt}
  AND ss.end_at <= #{endAt}
ORDER BY ss.start_at ASC, ss.session_number ASC

SELECT COUNT(1)
FROM slot_sessions ss
WHERE ss.assignment_id = #{assignmentId}
  AND ss.venue_id = #{venueId}
  AND DATE(ss.start_at) = DATE(#{date})
  AND NOT (ss.end_at <= #{startAt} OR ss.start_at >= #{endAt})
  AND ss.session_id <> #{excludeSessionId}

SELECT * FROM slot_sessions WHERE slot_id = #{slotId}
AND (start_at < #{startAt} OR end_at > #{endAt})
ORDER BY session_number ASC

mapper.delete:
DELETE FROM slot_sessions
WHERE slot_id = #{slotId}

  AND (start_at < #{startAt} OR end_at > #{endAt})

mapper.select:
SELECT COUNT(1) > 0
FROM slot_sessions ss
INNER JOIN time_slots ts ON ss.slot_id = ts.slot_id
WHERE ts.assignment_id = #{assignmentId}
  AND ss.booked_subject_type IN ('GROUP', 'MIX')
  AND ss.booked_subject_id = #{groupId}

SELECT DISTINCT ss.assignment_id FROM session_student st INNER JOIN slot_sessions ss ON st.session_id = ss.session_id WHERE ss.assignment_id IN
#{assignmentId}
AND ( (st.type = 'INDIVIDUAL' AND st.subject_id = #{studentId}) OR (st.type IN ('GROUP', 'MIX') AND st.subject_id IN ( SELECT sg.group_id FROM sys_student_group sg WHERE sg.user_id = #{studentId} )) )
